import * as THREE from 'three/webgpu';
import { texture } from 'three/tsl';

export default function createNode(config, ctx) {
  const group = new THREE.Group();

  // Load sprite texture
  const imageUrl = config.assets?.imageUrl || '/prism-mock/home/nodes/floating-accent.png';
  const spriteTexture = ctx.textureLoader.load(imageUrl);

  // Calculate plane geometry dimensions from atlas region aspect ratio
  // Atlas region: 512x320 pixels → aspect ratio 1.6
  const aspectRatio = 512 / 320;
  const height = 1.6; // Scene unit height
  const width = height * aspectRatio;

  // Create plane geometry
  const geometry = new THREE.PlaneGeometry(width, height);

  // Create material using TSL nodes
  const textureNode = texture(spriteTexture);
  const material = new THREE.MeshBasicNodeMaterial({
    colorNode: textureNode,
    transparent: true,
    side: THREE.DoubleSide,
    depthWrite: false,
  });

  // Create and configure mesh
  const mesh = new THREE.Mesh(geometry, material);
  mesh.position.set(0, -0.35, -0.6);
  mesh.rotation.set(0, 0, 0);
  mesh.scale.set(1, 1, 1);

  group.add(mesh);

  // Resource cleanup
  group.userData.cleanup = function() {
    geometry.dispose();
    material.dispose();
    spriteTexture.dispose();
  };

  // Event handlers (none for this static element)
  group.userData.handlers = {};

  return group;
}
